def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            safe_bid = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, safe_bid)))

    prev_bids = []
    urgent_prev_bids = []
    rich_prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev and prev.get('bid') is not None:
            bid = float(prev.get('bid'))
            prev_bids.append(bid)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_prev_bids.append(bid)
            if opp.get('budget', 0) > budget * 0.9:
                rich_prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_highest = max(urgent_prev_bids) if urgent_prev_bids else 0.0
    rich_highest = max(rich_prev_bids) if rich_prev_bids else 0.0

    tight_supply = supply <= 17.0
    roomy_supply = supply >= 22.0

    if hp <= 1 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif hp <= 3 or no_water_days >= 1:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.82, highest_prev + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.68, highest_prev + 1.0)
    else:
        if tight_supply:
            if highest_prev >= DAILY_SALARY * 1.8:
                bid = DAILY_SALARY * 0.58
            else:
                bid = max(DAILY_SALARY * 0.52, rich_highest + 1.5, highest_prev + 0.8)
        elif roomy_supply:
            if highest_prev >= DAILY_SALARY * 1.5:
                bid = DAILY_SALARY * 0.28
            else:
                bid = max(DAILY_SALARY * 0.34, highest_prev * 0.72)
        else:
            if urgent_highest > 0:
                bid = max(DAILY_SALARY * 0.48, urgent_highest + 1.0)
            else:
                bid = max(DAILY_SALARY * 0.42, highest_prev * 0.82)

    if day <= 2 and hp >= 8 and no_water_days == 0:
        bid = min(bid, DAILY_SALARY * 0.55)

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, max(budget, DAILY_SALARY * 0.45))

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Immediate reaction from yesterday's trace
    prev_bids = []
    prev_hp_after = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
                prev_hp_after.append(int(prev.get('hp_after', opp.get('hp', 0))))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    lowest_prev_bid = min(prev_bids) if prev_bids else 0.0

    # Pressure estimate: if someone paid a lot yesterday, they likely expected low marginal water.
    # We aim to be competitive but not wasteful.
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    high_supply = supply >= supply_mid

    # Convert our water need urgency into bid aggressiveness
    urgency = 0
    if my_hp <= 2:
        urgency += 3
    if my_hp == 3:
        urgency += 2
    if my_no_water_days >= 2:
        urgency += 2
    if my_no_water_days >= 3:
        urgency += 2

    # If Cindy-like behavior (very high bid yesterday) likely means others are willing to overpay.
    # We slightly undercut unless we are in danger.
    danger = (my_hp <= 3) or (my_no_water_days >= 3)

    # Base target bid cap based on supply
    if high_supply:
        base = DAILY_SALARY * 0.45
    else:
        base = DAILY_SALARY * 0.65

    # If yesterday highest bid was very high, assume a competitive market; bid near that threshold.
    if highest_prev_bid >= DAILY_SALARY * 1.5:
        if danger:
            target = min(my_budget, highest_prev_bid * 0.98)
        else:
            # Try to win with a small premium over likely median; avoid full matching.
            target = min(my_budget, max(base, highest_prev_bid * 0.85))
    elif highest_prev_bid >= DAILY_SALARY * 1.0:
        if danger:
            target = min(my_budget, highest_prev_bid * 0.9)
        else:
            target = min(my_budget, max(base, highest_prev_bid * 0.75))
    else:
        # Low competition yesterday: bid around base, but ensure we don't starve.
        if danger:
            target = min(my_budget, base * 1.25)
        else:
            target = min(my_budget, base)

    # Ensure we don't bid too low when our hp is already failing
    if my_hp <= 2:
        target = max(target, DAILY_SALARY * 0.85)
    elif my_hp == 3:
        target = max(target, DAILY_SALARY * 0.6)

    # Safety: never exceed budget
    if target > my_budget:
        target = my_budget

    # Small day-based adjustment to avoid ties late in episode
    # (episode length is 10; later days slightly increase)
    if day >= 8:
        target = min(my_budget, target * 1.06)

    return float(target)

