    today_supply = day_context['supply']
    # Calculate yesterday's average bid among alive opponents
    yest_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yest_bids.append(prev['bid'])
    if yest_bids:
        avg_yest_bid = sum(yest_bids) / len(yest_bids)
    else:
        avg_yest_bid = None

    hp = my_status['hp']
    budget = my_status['budget']

    # If HP is very low, we must get water
    if hp <= 2:
        bid = min(budget, DAILY_SALARY * 0.9)
    else:
        # Not desperate
        if avg_yest_bid is not None:
            if avg_yest_bid > DAILY_SALARY * 0.8:
                # Opponents are aggressive, conserve
                bid = min(budget, DAILY_SALARY * 0.3)
            else:
                # Opponents were moderate, try to win with slight edge
                bid = min(budget, avg_yest_bid * 1.2 + 1)
        else:
            # No history, first day: bid moderate
            bid = min(budget, DAILY_SALARY * 0.5)
    # Ensure non-negative
    bid = max(0, bid)
    return bid

